create table if not exists wa_identities (wa_number text primary key, person_id uuid not null references persons(person_id), status text not null default 'ACTIVE' check(status in ('ACTIVE','INACTIVE','BLOCKED')), created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create unique index if not exists uq_active_wa_number on wa_identities(wa_number) where status='ACTIVE';
create table if not exists automation_deliveries (delivery_id uuid primary key, event_id uuid not null references automation_events(event_id), recipient_person_id uuid not null references persons(person_id), channel text not null, idempotency_key text not null unique, status text not null default 'PENDING', provider_message_id text, attempt_count integer not null default 0, last_error text, scheduled_at timestamptz, sent_at timestamptz, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
